    [Theory]
    [MemberData(nameof(Sorts))]
    public void AQuicksortWhosePartsLeaveOutWhatEqualsThePivotIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The sorts keeping what equals the pivot; a part of its own for it, an else for it, or a third test for it; Lomuto's and
    /// Hoare's partitions, made in place; a tree that keeps each value once, as a set does; a quickselect, which goes on into
    /// one part chosen by a test; and two filters that are counted, not sorted again.
    /// </summary>
    [Theory]
    [InlineData("filtered.py", "def quicksort(items):\n    if len(items) < 2:\n        return items\n    pivot = items[-1]\n    rest = items[:-1]\n    below = list(filter(lambda item: item < pivot, rest))\n    above = list(filter(lambda item: item >= pivot, rest))\n    return quicksort(below) + [pivot] + quicksort(above)\n\n\nprint(*quicksort([3, 1, 2, 3, 1]))\n")]
    [InlineData("partition.py", "def quicksort(items):\n    if len(items) <= 1:\n        return items\n    pivot, *rest = items\n    smaller = []\n    larger = []\n    for item in rest:\n        if item < pivot:\n            smaller.append(item)\n        elif item >= pivot:\n            larger.append(item)\n    return quicksort(smaller) + [pivot] + quicksort(larger)\n\n\nprint(*quicksort([3, 1, 2, 3, 1]))\n")]
    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\nusing System.Linq;\n\npublic static class Program\n{\n    static List<int> QuickSort(List<int> items)\n    {\n        if (items.Count <= 1)\n        {\n            return items;\n        }\n\n        int pivot = items[0];\n        var rest = items.Skip(1).ToList();\n        var below = rest.Where(x => x < pivot).ToList();\n        var above = rest.Where(x => x >= pivot).ToList();\n        var sorted = QuickSort(below);\n        sorted.Add(pivot);\n        sorted.AddRange(QuickSort(above));\n        return sorted;\n    }\n\n    public static void Main()\n    {\n        Console.WriteLine(string.Join(\" \", QuickSort(new List<int> { 3, 1, 2, 3, 1 })));\n    }\n}\n")]
    [InlineData("quicksort.c", "#include <stdio.h>\n\nstatic void quicksort(int *items, int count) {\n    if (count <= 1) return;\n    int pivot = items[0];\n    int lower[16], higher[16];\n    int lowerCount = 0, higherCount = 0;\n    for (int i = 1; i < count; i++) {\n        if (items[i] < pivot) {\n            lower[lowerCount++] = items[i];\n        } else if (items[i] >= pivot) {\n            higher[higherCount++] = items[i];\n        }\n    }\n    quicksort(lower, lowerCount);\n    quicksort(higher, higherCount);\n    int at = 0;\n    for (int i = 0; i < lowerCount; i++) items[at++] = lower[i];\n    items[at++] = pivot;\n    for (int i = 0; i < higherCount; i++) items[at++] = higher[i];\n}\n\nint main(void) {\n    int numbers[] = {3, 1, 2, 3, 1};\n    quicksort(numbers, 5);\n    for (int i = 0; i < 5; i++) {\n        printf(i > 0 ? \" %d\" : \"%d\", numbers[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}\n")]
    [InlineData("quicksort.cpp", "#include <iostream>\n#include <vector>\n\nstd::vector<int> quicksort(const std::vector<int>& items) {\n    if (items.size() <= 1) return items;\n    int pivot = items[0];\n    std::vector<int> rest(items.begin() + 1, items.end());\n    std::vector<int> lower, higher;\n    for (int x : rest) {\n        if (x < pivot) {\n            lower.push_back(x);\n        } else if (x >= pivot) {\n            higher.push_back(x);\n        }\n    }\n    std::vector<int> sorted = quicksort(lower);\n    sorted.push_back(pivot);\n    for (int x : quicksort(higher)) sorted.push_back(x);\n    return sorted;\n}\n\nint main() {\n    std::vector<int> numbers = quicksort({3, 1, 2, 3, 1});\n    for (std::size_t i = 0; i < numbers.size(); i++) {\n        std::cout << (i > 0 ? \" \" : \"\") << numbers[i];\n    }\n    std::cout << std::endl;\n    return 0;\n}\n")]
    [InlineData("quicksort.dart", "List<int> quickSort(List<int> items) {\n  if (items.length <= 1) return items;\n  final pivot = items[0];\n  final rest = items.sublist(1);\n  final lower = rest.where((x) => x < pivot).toList();\n  final higher = rest.where((x) => x >= pivot).toList();\n  return [...quickSort(lower), pivot, ...quickSort(higher)];\n}\n\nvoid main() {\n  print(quickSort([3, 1, 2, 3, 1]).join(' '));\n}\n")]
    [InlineData("quicksort.erl", "-module(quicksort).\n-export([main/0]).\n\nquick_sort([]) -> [];\nquick_sort([Pivot | Rest]) ->\n    Lower = [X || X <- Rest, X < Pivot],\n    Higher = [X || X <- Rest, X >= Pivot],\n    quick_sort(Lower) ++ [Pivot] ++ quick_sort(Higher).\n\nmain() ->\n    Words = [integer_to_list(Number) || Number <- quick_sort([3, 1, 2, 3, 1])],\n    io:format(\"~s~n\", [lists:join(\" \", Words)]).\n")]
