    [InlineData("QuickSort.java", "import java.util.ArrayList;\nimport java.util.Arrays;\n\npublic class QuickSort {\n    static ArrayList<Integer> quicksort(ArrayList<Integer> items) {\n        if (items.isEmpty()) {\n            return new ArrayList<>();\n        }\n        Integer pivot = items.get(0);\n        ArrayList<Integer> lesser = new ArrayList<>();\n        ArrayList<Integer> greater = new ArrayList<>();\n        for (Integer x : items.subList(1, items.size())) {\n            if (x < pivot) {\n                lesser.add(x);\n            } else if (x >= pivot) {\n                greater.add(x);\n            }\n        }\n        ArrayList<Integer> sorted = quicksort(lesser);\n        sorted.add(pivot);\n        sorted.addAll(quicksort(greater));\n        return sorted;\n    }\n\n    public static void main(String[] args) {\n        ArrayList<Integer> numbers = quicksort(new ArrayList<>(Arrays.asList(3, 1, 2, 3, 1)));\n        StringBuilder line = new StringBuilder();\n        for (int number : numbers) {\n            if (line.length() > 0) line.append(' ');\n            line.append(number);\n        }\n        System.out.println(line);\n    }\n}\n")]
