    [InlineData("hoare.py", "def quicksort(items, lo, hi):\n    if lo >= hi:\n        return\n    pivot = items[(lo + hi) // 2]\n    i, j = lo, hi\n    while i <= j:\n        while items[i] < pivot:\n            i += 1\n        while items[j] > pivot:\n            j -= 1\n        if i <= j:\n            items[i], items[j] = items[j], items[i]\n            i += 1\n            j -= 1\n    quicksort(items, lo, j)\n    quicksort(items, i, hi)\n\n\nnumbers = [3, 1, 2, 3, 1]\nquicksort(numbers, 0, len(numbers) - 1)\nprint(*numbers)\n")]
    [InlineData("lomuto.c", "#include <stdio.h>\n\nstatic void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }\n\nstatic void quicksort(int *items, int lo, int hi) {\n    if (lo >= hi) return;\n    int pivot = items[hi];\n    int i = lo;\n    for (int j = lo; j < hi; j++) {\n        if (items[j] < pivot) {\n            swap(&items[i], &items[j]);\n            i++;\n        }\n    }\n    swap(&items[i], &items[hi]);\n    quicksort(items, lo, i - 1);\n    quicksort(items, i + 1, hi);\n}\n\nint main(void) {\n    int numbers[] = {3, 1, 2, 3, 1};\n    quicksort(numbers, 0, 4);\n    for (int i = 0; i < 5; i++) printf(i > 0 ? \" %d\" : \"%d\", numbers[i]);\n    printf(\"\\n\");\n    return 0;\n}\n")]
    [InlineData("select.py", "def kth_smallest(items, k):\n    pivot = items[0]\n    below = [x for x in items if x < pivot]\n    above = [x for x in items if x > pivot]\n    equal = len(items) - len(below) - len(above)\n    if k < len(below):\n        return kth_smallest(below, k)\n    elif k >= len(below) + equal:\n        return kth_smallest(above, k - len(below) - equal)\n    return pivot\n\n\nprint(kth_smallest([3, 1, 2, 3, 1], 2))\n")]
