    [InlineData("tree_set.py", "class Node:\n    def __init__(self, value):\n        self.value = value\n        self.left = None\n        self.right = None\n\n\ndef insert(node, value):\n    if node is None:\n        return Node(value)\n    if value < node.value:\n        node.left = insert(node.left, value)\n    elif value > node.value:\n        node.right = insert(node.right, value)\n    return node\n\n\ndef walk(node):\n    return walk(node.left) + [node.value] + walk(node.right) if node else []\n\n\nroot = None\nfor number in [3, 1, 2, 3, 1]:\n    root = insert(root, number)\nprint(*walk(root))\n")]
    public void APartitionThatKeepsWhatEqualsThePivotIsLeftAlone(string fileName, string code)
    {
        var file = Program(fileName, code);
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("partition-drops-equal", StringComparison.Ordinal)).SelectMany(pattern => pattern.Find(file)));
    }
